// Additive live inventory. Frozen 0.53/0.56 engines and studies are unchanged.
import{explorerResults as baseline,explorerCareerQuestions as originalQuestions,explorerAnswer,explorerEducation as originalEducation,explorerFieldQuestions,resolveExplorerRoute,discoveryTopics056,topicsPanel056,soundPanel056}from'./open-explorer-056.js';
import{explorerCatalog as originalCatalog}from'./open-explorer.js';
import{scoreOnetInterest,profileCorrelation,interestFit}from'./onet-assessment.js';
import{careerFamilies}from'./guide-state.js';
import{noncollege087}from'./noncollege-087-data.js';
export{explorerAnswer,explorerFieldQuestions,resolveExplorerRoute,discoveryTopics056,topicsPanel056,soundPanel056};
export const explorerCatalog=[...originalCatalog,...noncollege087];
const direct087={'carpentry':['onet-sf-01'],'construction-laborer':['onet-sf-02'],'hvac':['onet-sf-13'],'industrial-machinery-mechanic':['onet-sf-13','onet-sf-49'],'welder':['onet-sf-49'],'bookkeeping-clerk':['onet-sf-12','onet-sf-36','onet-sf-48'],'truck-driver':['onet-sf-26'],'farmworker-crops':['onet-sf-14']};
const byId=new Map(noncollege087.map(o=>[o.id,o]));
export const explorerCareerQuestions=id=>byId.get(id)?.questions||originalQuestions(id);
export const explorerEducation=o=>o.noncollege087?o.preparation.typicalEducation[0]:originalEducation(o);
const eligible=a=>a&&!a.reviewHold&&(a.source!=='profile-inferred'||['high','medium'].includes(a.confidence)&&!!a.evidence?.trim());
export function activityLinks087(s,o){const p=scoreOnetInterest(s);if(!p.complete||p.flat||p.nearFlat)return[];return (o.anchors||[]).filter(id=>Number(s.profileJourney?.officialInterest?.answers?.[id])>=4);}
export function evidence087(s,o){const evidence=[],contrary=[],asked=[],domains=[];for(const q of o.questions){const a=explorerAnswer(s,'profession',o.id,q);if(a)asked.push(q.id);if(!eligible(a))continue;if(a.response==='yes'){domains.push(q.domain);evidence.push({questionId:q.id,prompt:q.prompt,text:q.prompt,domain:q.domain,kind:'specific',source:a.source,confidence:a.confidence,evidence:a.evidence});}if(a.response==='no')contrary.push({questionId:q.id,prompt:q.prompt,source:a.source,evidence:a.evidence});}return{supported:domains.length===3&&!contrary.length,evidence,contrary,asked:asked.length,taskDomains:[],specificDomains:domains,taskDomainCount:0,inferred:evidence.some(a=>a.source==='profile-inferred'),missing:o.questions.filter(q=>!evidence.some(e=>e.questionId===q.id)),requirement:'Subject, method and distinctive responsibility need independent support.'};}
export function explorerResults(s,options={}){const old=baseline(s,options),interest=scoreOnetInterest(s),valid=interest.complete&&!interest.flat&&!interest.nearFlat;let additions=noncollege087.filter(o=>!options.scope||options.scope==='all'||o.fields.includes(options.scope)).filter(o=>!options.education||options.education==='all'||o.routes.some(r=>r.key===options.education)).filter(o=>!options.q||o.title.toLowerCase().includes(options.q.toLowerCase())).map(o=>{const r=valid?profileCorrelation(interest.raw,o.vector):null,specific=evidence087(s,o),activityTopics=activityLinks087(s,o);return{id:o.id,o,r,fields:o.fields,degree:false,directActivity087:!!activityTopics.length,band:interestFit(r).label,specific,activityTopics,activityStrength:activityTopics.length};});
 // Keep established supported ordering; additions can fill vacant Top slots without displacing existing degree fits.
 const previous=old.rows.map(r=>{const links=activityLinks087(s,{anchors:direct087[r.id]||[]});return links.length?{...r,directActivity087:true,activityTopics:[...new Set([...(r.activityTopics||[]),...links])]}:r;});let rows=[...previous.filter(r=>r.specific.supported),...additions.filter(r=>r.specific.supported),...previous.filter(r=>!r.specific.supported),...additions.filter(r=>!r.specific.supported)];if(options.sort==='correlation')rows.sort((a,b)=>(b.r??-2)-(a.r??-2));return{...old,rows,total:old.total+additions.length,version:'0.87.0'};}
export function explorerFieldSummary(s){const rows=explorerResults(s).rows;return careerFamilies.map(f=>({id:f.id,title:f.title,careers:rows.filter(r=>r.fields.includes(f.id)).slice(0,3),count:rows.filter(r=>r.fields.includes(f.id)).length}));}
export function salary087(id){const o=byId.get(id);if(!o)return null;const w=o.salary;return{careerId:id,planningOnly:true,entryComparable:false,geography:w.geography,referencePeriod:w.period,label:'Lower-paid-worker wage proxy · after qualification',stages:[{key:'entry',amount:w.entry},{key:'year5',amount:w.year5}],sources:[{publisher:'Texas Workforce Commission',title:'2025 occupational wage reference'+(w.broader?' · broader occupation group':''),url:w.sourceURL,referencePeriod:w.period}],notes:[w.basis,'Required preparation and credentials come before qualified-role pay.','Employee wage proxy; not a guaranteed offer or validated earnings by experience.'],confidence:'modeled'};}
